import { Controller, Delete, Get, Post, Req, Res } from '@nestjs/common';
import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
import type { Request, Response } from 'express';
import { Auth, CurrentActor } from '../auth/auth.decorators.js';
import type { Actor } from '../auth/auth.types.js';
import { McpServerService } from './mcp-server.service.js';

/**
 * The MCP endpoint (Streamable HTTP, stateless): `POST /mcp` with an API token. Each request
 * gets its own server bound to the caller, so nothing is shared between users or requests.
 */
@Auth('api_token')
@Controller('mcp')
export class McpController {
  constructor(private readonly servers: McpServerService) {}

  @Post()
  async handle(
    @CurrentActor() actor: Actor,
    @Req() req: Request,
    @Res() res: Response,
  ): Promise<void> {
    const server = this.servers.create(actor, String(req.id));
    // JSON responses, not SSE: every tool answers in one go.
    const transport = new StreamableHTTPServerTransport({
      sessionIdGenerator: undefined,
      enableJsonResponse: true,
    });
    res.on('close', () => void server.close());
    await server.connect(transport);
    await transport.handleRequest(req, res, req.body);
  }

  /** A stateless server has no stream to open. */
  @Get()
  openStream(@Res() res: Response): void {
    methodNotAllowed(res);
  }

  /** A stateless server has no session to end. */
  @Delete()
  endSession(@Res() res: Response): void {
    methodNotAllowed(res);
  }
}

function methodNotAllowed(res: Response): void {
  res
    .status(405)
    .set('Allow', 'POST')
    .json({
      jsonrpc: '2.0',
      error: { code: -32000, message: 'Method not allowed: send JSON-RPC requests with POST.' },
      id: null,
    });
}
import { type CanActivate, type ExecutionContext, Inject, Injectable } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ErrorCode } from '@artifact-hub/shared';
import type { Request, Response } from 'express';
import { InjectPinoLogger, PinoLogger } from 'nestjs-pino';
import { AppError } from '../common/errors/app-error.js';
import { AUTH_SCHEMES_KEY, IS_PUBLIC_KEY } from './auth.decorators.js';
import type { AuthScheme, RequestAuthenticator } from './auth.types.js';

/** Every registered `RequestAuthenticator` (see `AuthModule.register`). */
export const REQUEST_AUTHENTICATORS = Symbol('REQUEST_AUTHENTICATORS');

const DEFAULT_SCHEMES: AuthScheme[] = ['session'];

/**
 * Global guard: every route requires credentials unless marked `@Public()`. A session by
 * default; `@Auth(...)` names others. Sets `req.authentication` and adds the user to the request's log
 * lines. Fails closed: other transports, and schemes nobody registered, are errors.
 */
@Injectable()
export class AuthGuard implements CanActivate {
  private readonly authenticators: Map<AuthScheme, RequestAuthenticator>;

  constructor(
    private readonly reflector: Reflector,
    @Inject(REQUEST_AUTHENTICATORS) authenticators: RequestAuthenticator[],
    @InjectPinoLogger(AuthGuard.name) private readonly logger: PinoLogger,
  ) {
    this.authenticators = new Map();
    for (const authenticator of authenticators) {
      if (this.authenticators.has(authenticator.scheme)) {
        throw new Error(`Two authenticators for the '${authenticator.scheme}' scheme`);
      }
      this.authenticators.set(authenticator.scheme, authenticator);
    }
  }

  async canActivate(context: ExecutionContext): Promise<boolean> {
    // A new transport (websockets, microservices) must bring its own authentication.
    if (context.getType() !== 'http') {
      throw new Error(`AuthGuard only supports HTTP, not '${context.getType()}'`);
    }
    const targets = [context.getHandler(), context.getClass()];
    if (this.reflector.getAllAndOverride<boolean | undefined>(IS_PUBLIC_KEY, targets)) return true;
    const schemes =
      this.reflector.getAllAndOverride<AuthScheme[] | undefined>(AUTH_SCHEMES_KEY, targets) ??
      DEFAULT_SCHEMES;

    const req = context.switchToHttp().getRequest<Request>();
    const res = context.switchToHttp().getResponse<Response>();
    const accepted = schemes.map((scheme) => {
      const authenticator = this.authenticators.get(scheme);
      if (!authenticator) throw new Error(`No authenticator registered for '${scheme}'`);
      return authenticator;
    });
    for (const authenticator of accepted) {
      const auth = await authenticator.authenticate(req, res);
      if (!auth) continue;
      req.authentication = auth;
      this.logger.assign({
        userId: auth.actor.userId,
        ...(auth.scheme === 'api_token' ? { tokenId: auth.apiTokenId } : {}),
      });
      return true;
    }
    throw new AppError(ErrorCode.UNAUTHENTICATED, accepted[0]!.missingCredentialsMessage);
  }
}
import {
  applyDecorators,
  createParamDecorator,
  type ExecutionContext,
  SetMetadata,
} from '@nestjs/common';
import type { Request } from 'express';
import { API_TOKEN_THROTTLER, UseThrottlers } from '../common/rate-limit/rate-limit.module.js';
import type { Actor, AuthScheme } from './auth.types.js';

export const IS_PUBLIC_KEY = 'auth:isPublic';
export const AUTH_SCHEMES_KEY = 'auth:schemes';

/** Opts a route (or controller) out of authentication. Everything else requires a session. */
export const Public = () => SetMetadata(IS_PUBLIC_KEY, true);

/**
 * The credentials a route (or controller) accepts, tried in this order, instead of a session
 * only. Routes accepting an API token are rate limited per user; they can't add other throttlers
 * with `@UseThrottlers()`, which would skip this one.
 */
export const Auth = (...schemes: [AuthScheme, ...AuthScheme[]]) =>
  schemes.includes('api_token')
    ? applyDecorators(SetMetadata(AUTH_SCHEMES_KEY, schemes), UseThrottlers(API_TOKEN_THROTTLER))
    : SetMetadata(AUTH_SCHEMES_KEY, schemes);

/** The authenticated `Actor`. Only valid on routes that are not `@Public()`. */
export const CurrentActor = createParamDecorator((_data: unknown, ctx: ExecutionContext): Actor => {
  const actor = ctx.switchToHttp().getRequest<Request>().authentication?.actor;
  if (!actor) throw new Error('@CurrentActor() used on a route that is not authenticated');
  return actor;
});
